CREATE OR REPLACE FUNCTION public.save_study_week_service(p_user uuid,p_week date,p_summary text,p_insights jsonb,p_sessions jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE pid uuid; item jsonb; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('study:'||p_user::text,0)); INSERT INTO public.study_plans(user_id,week_start,summary,insights) VALUES(p_user,p_week,p_summary,p_insights) ON CONFLICT(user_id,week_start) DO UPDATE SET summary=excluded.summary,insights=excluded.insights,generated_at=now() RETURNING id INTO pid; DELETE FROM public.study_sessions WHERE user_id=p_user AND plan_id=pid AND status='planejada'; FOR item IN SELECT * FROM jsonb_array_elements(p_sessions) LOOP INSERT INTO public.study_sessions(user_id,plan_id,topic_id,date,start_minutes,duration,type,format) VALUES(p_user,pid,item->>'topic_id',(item->>'date')::date,(item->>'start_minutes')::integer,(item->>'duration')::integer,item->>'type',item->>'format'); END LOOP; RETURN pid; END $$; REVOKE EXECUTE ON FUNCTION public.save_study_week_service(uuid,date,text,jsonb,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.save_study_week_service(uuid,date,text,jsonb,jsonb) TO service_role;